/* ---------- Score explicable sur 18 (6 critères de 0 à 3, poids égaux) ----------
   L'accessibilité du donneur d'ordre est un jugement commercial : non évaluée
   par défaut (0), elle peut être saisie dans le navigateur. */
const SCORE_CRITERES = [
  ["adq", "Adéquation technique"], ["mat", "Maturité industrielle"], ["vol", "Volume ou récurrence"],
  ["prox", "Proximité de la décision"], ["acc", "Accessibilité du donneur d'ordre"], ["qual", "Qualité et fraîcheur des sources"]
];
function moisEntre(a, b) { // a, b : "AAAA", "AAAA-MM" ou "AAAA-MM-JJ"
  const p = s => { const [y, m] = String(s).split("-"); return +y * 12 + (m ? +m - 1 : 11); };
  return p(b) - p(a);
}
function scoreOpp(o, acc) {
  const r = {};
  r.adq = o.lotDoc ? [3, "Lot ou fournisseur cité par une source"] : o.vol && (o.phase === "cd" || o.phase === "serie") ? [2, "Engin complet en fabrication, lot non documenté"] : o.vol ? [1, "Matériel de vol prévu, sous-ensembles incertains"] : [0, "Pas encore de matériel de vol"];
  const ph = PHASES[o.phase] || PHASES.nd;
  r.mat = [ph.m, ph.nom];
  const n = o.qte && o.qte.n;
  r.vol = n == null ? [0, "Quantité non documentée"] : n > 20 ? [3, n + " unités (plus de 20)"] : n >= 5 ? [2, n + " unités (5 à 20)"] : n >= 2 ? [1, n + " unités (2 à 4)"] : [0, "Unité seule"];
  if (!o.ech) r.prox = [0, "Échéance inconnue"];
  else {
    const m = moisEntre(DATE_VERIF, o.ech.d);
    const lib = (o.ech.doc ? "" : "estimation : ") + (m < 0 ? "échéance passée" : `dans ${m} mois environ`);
    r.prox = m < 0 ? [0, lib] : !o.ech.doc ? [1, lib] : m <= 12 ? [3, lib] : m <= 24 ? [2, lib] : [1, lib];
  }
  r.acc = acc == null ? [0, "Non évalué (à saisir)"] : [acc, "Saisi par l'utilisateur"];
  const pubs = o.sources.filter(s => s && s.pub).map(s => s.pub).sort();
  const last = pubs.length ? pubs[pubs.length - 1] : null;
  const age = last ? moisEntre(last, DATE_VERIF) : null;
  const vf = o.sources.filter(s => s).every(s => moisEntre(s.verif, DATE_VERIF) <= 6);
  r.qual = age != null && age > 24 ? [0, "Source la plus récente de plus de 2 ans"]
    : o.bc === "A" && vf ? [3, "Confiance A, vérifiée il y a moins de 6 mois" + (last ? "" : " (date de publication non documentée)")]
    : o.bc === "A" || o.bc === "B" ? [2, "Confiance " + o.bc] : [1, "Confiance C"];
  r.total = SCORE_CRITERES.reduce((s, [k]) => s + r[k][0], 0);
  return r;
}
